/**
 * Public glossary term count + phrasing (single source for marketing copy).
 * Canonical data: glossary_terms.json → all_terms (regenerate via scripts/sync_glossary_term_count.py).
 */
(function (global) {
  "use strict";

  var SOURCE_FILE = "glossary_terms.json";

  /** Regenerated by scripts/sync_glossary_term_count.py — do not edit by hand. */
  var TERM_COUNT = 1707;

  function resolvedCount() {
    if (global.GLOSSARY && global.GLOSSARY.length) return global.GLOSSARY.length;
    return TERM_COUNT;
  }

  function formatCount(n) {
    return Number(n == null ? resolvedCount() : n).toLocaleString("en-AU");
  }

  function brandLabel(n) {
    return formatCount(n) + "-term Glossary";
  }

  function countPlus(n) {
    return formatCount(n) + "+";
  }

  function legalTermsPhrase(n) {
    return formatCount(n) + "+ legal terms";
  }

  function termLegalGlossaryPhrase(n) {
    return formatCount(n) + "+ term legal glossary";
  }

  function familyLawTermsPhrase(n) {
    return formatCount(n) + "+ family law terms in plain English";
  }

  function glossaryIncludedPhrase(n) {
    return formatCount(n) + "-term glossary included";
  }

  function drawnFromGlossaryPhrase(n) {
    return "Drawn from our " + brandLabel(n) + " and legislation";
  }

  function connectedToGlossaryPhrase(n) {
    return "Connected to our " + countPlus(n) + " term Glossary";
  }

  function heroBrowsePhrase(n) {
    return "plain English definitions of " + countPlus(n) + " terms.";
  }

  function legislationLinkedPhrase(n) {
    return "Built from " + countPlus(n) + " glossary and legislation-linked entries";
  }

  function metaDescriptionPhrase(n) {
    return (
      "CasePath helps Australians navigate family court. Free guides, document preparation tools, and a " +
      brandLabel(n) +
      "."
    );
  }

  function metaLegalTermsPhrase(n) {
    return legalTermsPhrase(n) + " explained in plain English";
  }

  function hydrateCountFromLoadedGlossary() {
    if (global.GLOSSARY && global.GLOSSARY.length) {
      TERM_COUNT = global.GLOSSARY.length;
      if (global.CasePathGlossaryPublic) global.CasePathGlossaryPublic.TERM_COUNT = TERM_COUNT;
    }
  }

  function applyPlaceholders(root) {
    var scope = root || document;
    if (!scope || !scope.querySelectorAll) return;
    var map = {
      hyphen: brandLabel,
      plus: countPlus,
      legal: legalTermsPhrase,
      "legal-glossary": termLegalGlossaryPhrase,
      "family-law-terms": familyLawTermsPhrase,
      included: glossaryIncludedPhrase,
      drawn: drawnFromGlossaryPhrase,
      connected: connectedToGlossaryPhrase,
      hero: heroBrowsePhrase,
      count: formatCount,
      legislation: legislationLinkedPhrase,
    };
    scope.querySelectorAll("[data-casepath-glossary-label]").forEach(function (el) {
      var kind = el.getAttribute("data-casepath-glossary-label");
      if (map[kind]) el.textContent = map[kind]();
    });
  }

  function applyMetaPlaceholders(root) {
    var scope = root || document;
    if (!scope || !scope.querySelectorAll) return;
    var metaMap = {
      description: metaDescriptionPhrase,
      "legal-plain": metaLegalTermsPhrase,
      legislation: legislationLinkedPhrase,
    };
    scope.querySelectorAll("[data-casepath-glossary-meta]").forEach(function (el) {
      var kind = el.getAttribute("data-casepath-glossary-meta");
      if (metaMap[kind]) {
        var val = metaMap[kind]();
        if (el.tagName === "META") {
          el.setAttribute("content", val);
        } else {
          el.textContent = val;
        }
      }
    });
  }

  function bootPublicMeta() {
    applyPlaceholders(document);
    applyMetaPlaceholders(document);
  }

  var api = {
    SOURCE_FILE: SOURCE_FILE,
    TERM_COUNT: TERM_COUNT,
    count: resolvedCount,
    formatCount: formatCount,
    brandLabel: brandLabel,
    countPlus: countPlus,
    legalTermsPhrase: legalTermsPhrase,
    termLegalGlossaryPhrase: termLegalGlossaryPhrase,
    familyLawTermsPhrase: familyLawTermsPhrase,
    glossaryIncludedPhrase: glossaryIncludedPhrase,
    drawnFromGlossaryPhrase: drawnFromGlossaryPhrase,
    connectedToGlossaryPhrase: connectedToGlossaryPhrase,
    heroBrowsePhrase: heroBrowsePhrase,
    legislationLinkedPhrase: legislationLinkedPhrase,
    metaDescriptionPhrase: metaDescriptionPhrase,
    metaLegalTermsPhrase: metaLegalTermsPhrase,
    hydrateCountFromLoadedGlossary: hydrateCountFromLoadedGlossary,
    applyPlaceholders: applyPlaceholders,
    applyMetaPlaceholders: applyMetaPlaceholders,
    bootPublicMeta: bootPublicMeta,
  };

  global.CasePathGlossaryPublic = api;
  global.casepathGlossaryBrandLabel = brandLabel;
  global.casepathGlossaryCountPlus = countPlus;
  global.casepathGlossaryLegalTermsPhrase = legalTermsPhrase;
  global.casepathGlossaryDrawnFromPhrase = drawnFromGlossaryPhrase;

  if (typeof document !== "undefined") {
    if (document.readyState === "loading") {
      document.addEventListener("DOMContentLoaded", bootPublicMeta);
    } else {
      bootPublicMeta();
    }
  }
})(typeof window !== "undefined" ? window : this);
